            case SFnDecl(_,h,_,_,_) =>
              val eq2 = inComp.exists(r => equalMember(l, r))
              cause = addMessage(cause,
                                 "different method " + h.getName +
                                 " @ " + NodeUtil.getSpan(l))
          }
        eq
      }
      (inAPI.forall(handleOne), cause)
    }

